/** Der Kanal, auf dem die Karts der anderen fahren. */
const CHANNEL = 'kart';
/** Zwanzig Posen in der Sekunde: genug für ein Kart, wenig für einen Datenkanal. */
const SEND_INTERVAL = 1 / 20;
/**
 * Ein fremdes Kart läuft der empfangenen Pose weich hinterher statt auf sie zu
 * springen — zwischen zwei Nachrichten liegt bei Tempo 60 fast ein Meter.
 */
const FOLLOW_TAU = 0.06;
/** Ab diesem Abstand wird doch gesprungen: ein verlorenes Paket, ein Reset. */
const SNAP_DISTANCE = 3;

/** Half the width of the tarmac — die halbe Korridorbreite (`kartCourse.ts`). */
const HALF_WIDTH = KART_COURSE.halfWidth;
/** How far apart the tyre stacks along the edge stand. */
const BARRIER_SPACING = 5.5;
/** How far out from the tarmac the barriers sit. */
const BARRIER_OFFSET = 1.1;
/**
 * Wie weit Randstein und Reifenstapel von der Boxengasse wegbleiben.
 *
 * Sie werden aus der Mittellinie abgeleitet und wüssten sonst nichts davon,
 * dass an der Zielgeraden gar kein Rand ist, sondern die Gasse — und stünden
 * mitten zwischen den Karts.
 */
const PIT_CLEAR = 1.2;
/** Die Flächen neben der Strecke, auf denen ein Kart auch fahren darf. */
const APRONS = [PIT_APRON];
/** Stick deflection that counts as a scroll on the clipboard, and re-arms it. */
const SCROLL_ON = 0.55;
const SCROLL_OFF = 0.3;
const SCROLL_FIRST_DELAY = 0.42;
const SCROLL_REPEAT = 0.16;
/** How quickly the stick steering follows the stick, in units per second. */
const STEER_RATE = 3.4;
/** Keys that drive a kart from a desk. */
type FlatJob = 'throttle' | 'brake' | 'left' | 'right' | 'exit';
const FLAT_KEYS: Record<string, FlatJob> = {
  KeyW: 'throttle',
  ArrowUp: 'throttle',
  KeyS: 'brake',
  ArrowDown: 'brake',
  KeyA: 'left',
  ArrowLeft: 'left',
  KeyD: 'right',
  ArrowRight: 'right',
  // There is no A button on a keyboard, so the way out gets a key of its own.
  KeyE: 'exit',
};

const _hand = new THREE.Vector3();
const _hub = new THREE.Vector3();
const _head = new THREE.Vector3();
const _seat = new THREE.Vector3();
const _spot = new THREE.Vector3();
const _quaternion = new THREE.Quaternion();

/**
 * A little go-kart circuit.
 *
 * **Die Strecke ist gebaut und nicht gezeichnet.** Sie besteht aus Geraden und
 * Kurven auf dem Kachelgitter (`kartCourse.ts`) — vier Kurven mit vier
 * verschiedenen Radien und vier Geraden dazwischen —, und alles Weitere folgt
 * daraus: der Asphalt, die Randsteine, die Reifenstapel, wo die Runde anfängt
 * und wie lang sie ist. Wer die Bahn ändern will, ändert eine Liste; eine
 * spätere Bauwelt ändert dieselbe Liste mit der Hand.
 *
 * **Die Karts stehen in der Boxengasse**, die kachelbündig an der Zielgeraden
 * liegt (`kartPit.ts`): vier Buchten unter einem Dach, davor der Asphalt der
 * Gasse. Von dort fährt man los, indem man nach rechts auf die Gerade zieht —
 * es gibt keine Ein- und keine Ausfahrt, weil Gasse und Strecke aneinander
 * stoßen.
 *
 * **Take hold of the steering wheel** (grab, or point at it and pull) and you
 * are sitting in it; from then on the **right trigger is the throttle, the
 * left one the brake** and the **left stick steers** — or the wheel itself
 * does, if the first line of the clipboard says so.
 *
 * Getting out again is the one thing a new driver cannot guess, so it is
 * written on a sign right behind the steering wheel the whole time you are
 * sitting there: **hold A/X**, with a bar that fills up while you do. The same
 * thing sits as the first line on the clipboard, for anybody who would rather
 * point at it.
 *
 * **Der Kopf ist nicht am Kart festgeschraubt.** Er zieht der Lenkung nach
 * (`kartView.ts`), und wie weit, steht auf dem Klemmbrett. Das ist die eine
 * Zeile in dieser Welt, die gegen Übelkeit gebaut ist und nicht für das
 * Fahrgefühl — auch wenn sie beides verbessert.
 *
 * The clipboard is the pistol's settings menu in kart form: acceleration, top
 * speed, braking, traction, wheel spin, head lag, weight, steering lock,
 * wheelbase and reverse, each one stepping through its notches and showing the
 * raw figure it is at.
 *
 * Everything else is the portal lab's — the same hands, the same physics, the
 * same shared session. The belt starts out empty here: both triggers have a
 * job in this world.
 */
/** Was auf dem Kanal hin und her geht. */
type KartMessage =
  /** „Ich bin neu hier — wer sitzt wo?" */
  | { t: 'hello' }
  /** Ein Platz wird beansprucht oder geräumt. */
  | { t: 'seat'; kart: number | null; name: string }
  /** Eine Pose samt Rundenstand, zwanzigmal in der Sekunde. */
  | {
      t: 'drive';
      kart: number;
      x: number;
      z: number;
      yaw: number;
      steer: number;
      laps: number;
      progress: number;
      last: number | null;
      best: number | null;
    }
  /** Jemand hat alle Karts in die Box gestellt. */
  | { t: 'home' };

/** Ein Mitspieler in einem Kart, so wie er hier ankommt. */
interface Rival {
  name: string;
  /** Der Index des Karts, in dem er sitzt. */
  kart: number;
  laps: number;
  progress: number;
  lastLap: number | null;
  bestLap: number | null;
  /** Wohin sein Kart unterwegs ist — dorthin wird nachgezogen. */
  target: { x: number; z: number; yaw: number };
  steer: number;
  /** Die erste Nachricht setzt, jede weitere zieht nach. */
  primed: boolean;
}

export class KartWorld extends GridWorld {
  /** Die Mittellinie, aus den Streckenteilen gelegt (`kartCourse.ts`). */
  private readonly path = KART_COURSE.centre;
  private readonly lapLength = pathLength(this.path);

  private readonly tarmac = new THREE.MeshStandardMaterial({ color: 0x3a3f4a, roughness: 0.95 });
  private readonly paint = new THREE.MeshBasicMaterial({ color: 0xf2f4f8, toneMapped: false });
  private readonly kerbRed = new THREE.MeshStandardMaterial({ color: 0xd8402f, roughness: 0.8 });
  private readonly kerbWhite = new THREE.MeshStandardMaterial({ color: 0xf0f2f6, roughness: 0.8 });
  private readonly tyre = new THREE.MeshStandardMaterial({ color: 0x1b1e26, roughness: 0.95 });
  private readonly panel = new THREE.MeshStandardMaterial({
    color: 0xf2f4f8,
    roughness: 0.6,
    metalness: 0.05,
  });

  private readonly karts: Kart[] = [];
  private readonly kartBodies = new Map<Kart, PhysicsBody>();
  private readonly boardTargets: THREE.Object3D[] = [];

  private driving: Kart | null = null;
  /**
   * **Der Helm von innen** — der Visierrand an der Kamera
   * (`core/headgear.ts`).
   *
   * Er hängt an der Kamera und liegt auf `LAYER_HUD`, aus demselben Grund wie
   * die Trefferanzeige: Ein Rahmen, der dem Kopf ein Bild hinterherläuft, ist
   * genau das Gegenteil dessen, wofür es ihn gibt — und einer, den auch die
   * Portalkameras zeichnen, schwebte als schwarzer Ring im Raum.
   */
  private visor: THREE.Mesh | null = null;
  /** Seconds A/X has been held down while seated. */
  private exitHeld = 0;
  /** The hand on the steering wheel, and where around it that hand last was. */
  private wheelGrab: { hand: Handedness; angle: number } | null = null;
  /** Stick steering, eased so a flick of the thumb is not a flick of the kart. */
  private steer = 0;
  /**
   * Wohin der **Blick** zeigt, während das Kart schon woanders hinzeigt.
   *
   * Der Rig wird jeden Frame auf diesen Winkel gestellt und nicht auf den des
   * Karts — das ist der ganze Nachlauf (`kartView.ts`). Beim Einsteigen sind
   * die beiden gleich, danach läuft dieser hinterher.
   */
  private viewYaw = 0;
  /** Der eigene Rundenstand (`kartRace.ts`, mit Test). */
  private lap: LapState = startLap(0);
  /** Die Mitfahrer, nach Peer-Id — jeder in genau einem Kart. */
  private readonly rivals = new Map<string, Rival>();
  private sendTimer = 0;
  private lapBoard: TextPlane | null = null;
  private boardTick = 0;

  private scrollArmed = true;
  private scrollTimer = 0;

  /** Keys held down, for driving without a headset. */
  private readonly pressed = new Set<string>();
  private onKeyDown: ((event: KeyboardEvent) => void) | null = null;
  private onKeyUp: ((event: KeyboardEvent) => void) | null = null;

  override async init(ctx: WorldContext): Promise<void> {
    await super.init(ctx);

    for (const kart of this.karts) {
      // The wheel answers to the pointer as well as to a hand: on a flat screen
      // there is no hand to reach out with.
      ctx.pointer.add({
        object: kart.wheelTarget,
        pokeable: false,
        // Once somebody is sitting in a kart, no steering wheel listens to a
        // laser any more: there is nothing left to select, and a ray resting
        // on the wheel in front of you would swallow the throttle trigger.
        ignore: () => this.driving !== null || this.takenByOther(kart),
        onSelect: () => this.enter(ctx, kart),
      });
      ctx.pointer.add(kart.board.asPointerTarget());
      this.boardTargets.push(kart.wheelTarget, kart.board);
      this.showBoard(kart);
    }

    // Ein Rennen ist erst eines, wenn das Kart des anderen mitfährt.
    ctx.net.on(CHANNEL, (data, from) => this.receive(ctx, data as KartMessage, from));
    ctx.net.emit(CHANNEL, { t: 'hello' } satisfies KartMessage);

    this.onKeyDown = (event) => {
      if (FLAT_KEYS[event.code]) this.pressed.add(event.code);
    };
    this.onKeyUp = (event) => this.pressed.delete(event.code);
    window.addEventListener('keydown', this.onKeyDown);
    window.addEventListener('keyup', this.onKeyUp);
  }

  override update(dt: number, ctx: WorldContext): void {
    super.update(dt, ctx);

    if (this.driving) this.updateDriving(dt, ctx, this.driving);
    else this.checkBoarding(ctx);
    this.updateRivals(dt, ctx);
    this.updateSend(dt);

    ctx.rig.getHeadPosition(_head);
    for (const kart of this.karts) kart.faceHover(_head);
    this.updateScroll(dt, ctx);

    this.boardTick += dt;
    if (this.boardTick >= 0.25) {
      this.boardTick = 0;
      this.drawLapBoard();
    }
  }

  override dispose(ctx: WorldContext): void {
    // Erst aussteigen, dann abmelden: der Platz soll nicht besetzt bleiben,
    // nur weil jemand die Welt gewechselt hat.
    if (this.driving) this.leave(ctx);
    ctx.net.emit(CHANNEL, { t: 'seat', kart: null, name: ctx.net.name } satisfies KartMessage);
    ctx.net.off(CHANNEL);
    this.rivals.clear();
    if (this.onKeyDown) window.removeEventListener('keydown', this.onKeyDown);
    if (this.onKeyUp) window.removeEventListener('keyup', this.onKeyUp);
    this.onKeyDown = null;
    this.onKeyUp = null;
    this.pressed.clear();

    for (const object of this.boardTargets) ctx.pointer.remove(object);
    this.boardTargets.length = 0;
    ctx.rig.frozen = false;
    this.driving = null;
    this.wheelGrab = null;
    for (const kart of this.karts) kart.disposeKart();
    this.karts.length = 0;
    this.kartBodies.clear();
    this.lapBoard?.dispose();
    this.lapBoard = null;
    super.dispose(ctx);
  }

  override menu(): MenuEntry[] {
    return [
      ...super.menu(),
      {
        id: 'kart:home',
        label: 'Karts in die Box',
        sub: 'Alle vier zurück in ihre Bucht',
        icon: 'reset',
        accent: 0xffc857,
        run: () => {
          if (this.driving) this.leave(this.context!);
          for (const kart of this.karts) {
            kart.returnHome();
            this.syncBody(kart);
          }
          this.context?.net.emit(CHANNEL, { t: 'home' } satisfies KartMessage);
          this.context?.notify('Karts stehen wieder in der Box');
        },
      },
      {
        id: 'kart:times',
        label: 'Zeiten löschen',
        sub: 'Letzte und beste Runde vergessen',
        icon: 'stopwatch',
        accent: 0x5ee0a0,
        run: () => {
          this.lap = { ...this.lap, laps: 0, lastLap: null, bestLap: null };
          this.announceSeat();
          this.drawLapBoard();
          this.context?.notify('Rundenzeiten gelöscht');
        },
      },
    ];
  }

  /** `B`/`Y` stellt alle Karts zurück in die Boxengasse, Fahrer und alles. */
  protected override worldReset(): void {
    if (this.driving && this.context) this.leave(this.context);
    for (const kart of this.karts) {
      kart.returnHome();
      this.syncBody(kart);
    }
  }

  /** Am Südende der Boxengasse, mit Blick auf die Reihe der Karts. */
  protected override spawnPoint(): THREE.Vector3 {
    return new THREE.Vector3((PIT_APRON.x0 + PIT_APRON.x1) / 2, 0, PIT_APRON.z1 - 3.5);
  }

  /** Nach Norden, also die Gasse entlang — bei `yaw = 0` schaut man auf −Z. */
  protected override spawnYaw(): number {
    return 0;
  }

  protected override skyColor(): number {
    return 0xa9c9ea;
  }

  /** Die Fläche bis zum Horizont ist hier Wiese, wie das Gelände auch. */
  protected override horizonColor(): number {
    return 0x5d8449;
  }

  protected override lightIntensity(): number {
    return 1.15;
  }

  protected override welcome(): string {
    return 'Lenkrad greifen zum Einsteigen · Aussteigen: A/X halten';
  }

  /** Both triggers have a job here, so the belt starts out empty. */
  protected override beltLoadout(): ReadonlyArray<readonly [string, Handedness]> {
    return [];
  }

  /** Unter diesem Namen liegt die Welt im Speicher (`grid/worldStore.ts`). */
  protected override worldId(): string {
    return 'kart';
  }

  protected override editorTitle(): string {
    return 'Gokart';
  }

  /** Wiese, Boxengasse, Boxen — alles, was Kachelform hat (`kartPit.ts`). */
  protected override layout(): GridPlan {
    return kartPit();
  }

  /**
   * Die Palette der Gitterwelten, an zwei Stellen verstellt: Der Boden ist
   * hier Wiese und der Stein Asphalt. Alles andere — Wände, Dach, Säulen,
   * Tafeln — sieht aus wie in jeder anderen Gitterwelt, und genau das ist der
   * Sinn einer gemeinsamen Palette.
   */
  protected override tint(): Partial<Record<PlanSolidKind, number>> {
    return { floor: 0x6f9a58, stone: 0x3a3f4a };
  }

  protected override buildEnvironment(): void {
    // Erst der Grundriss (und mit ihm die Requisiten), dann die Strecke: Was
    // aus Kacheln kommt, kommt aus dem Plan, und was eine Kurve ist, wird
    // danach als Band darübergelegt.
    super.buildEnvironment();

    const circuit = new THREE.Group();
    circuit.name = 'kart-circuit';
    this.root.add(circuit);
    this.root.add(createSky(0x6ea8e8, 0xdbe7f2));

    this.buildRoad(circuit);
    this.buildKerbs(circuit);
    this.buildBarriers(circuit);
    this.buildStart(circuit);
    this.buildPitLane();
  }

  /** Cones on the track: the one thing a kart is guaranteed to hit. */
  protected override buildProps(): void {
    const physics = this.physics!;
    const material = new THREE.MeshStandardMaterial({ color: 0xff8a2f, roughness: 0.8 });
    // Along the middle of the lap, a little off line so they can be dodged.
    for (let i = 0; i < 10; i++) {
      const point = this.path[Math.floor((i + 0.5) * (this.path.length / 10))]!;
      const hit = nearestOnPath(this.path, point.x, point.z);
      const side = i % 2 === 0 ? 1 : -1;
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.5, 12), material);
      cone.position.set(hit.x + hit.tz * side * 1.9, 0.25, hit.z - hit.tx * side * 1.9);
      this.root.add(cone);
      this.registerProp(
        physics.addDynamic(cone, {
          shape: { kind: 'cone' },
          halfExtents: new THREE.Vector3(0.16, 0.25, 0.16),
          mass: 1.2,
          friction: 0.7,
          restitution: 0.1,
        }),
        `kart-cone-${i}`,
      );
    }
  }

  // --- getting in and out ---------------------------------------------------

  /** A hand that closes around a steering wheel is a driver getting in. */
  private checkBoarding(ctx: WorldContext): void {
    for (const controller of ctx.input.controllers) {
      if (!controller.tracked || !controller.squeeze.justPressed) continue;
      gripAnchor(controller).getWorldPosition(_hand);
      for (const kart of this.karts) {
        kart.hubPosition(_hub);
        if (_hand.distanceTo(_hub) > WHEEL_GRAB_RANGE) continue;
        this.enter(ctx, kart);
        controller.pulse(0.6, 40);
        return;
      }
    }
  }

  private enter(ctx: WorldContext, kart: Kart): void {
    if (this.driving) return;
    if (this.takenByOther(kart)) {
      ctx.notify(`${kart.preset.name} ist besetzt`);
      return;
    }
    this.driving = kart;
    this.exitHeld = 0;
    this.applyHelmet();
    this.steer = 0;
    this.wheelGrab = null;
    // Beim Einsteigen schaut man dorthin, wohin das Kart schaut; erst ab dem
    // ersten Lenkeinschlag läuft der Blick hinterher.
    this.viewYaw = kart.motion.yaw;
    this.lap = startLap(nearestOnPath(this.path, kart.motion.x, kart.motion.z).along);
    kart.setSeated(true);
    ctx.rig.frozen = true;
    this.seatDriver(ctx, kart);
    this.announceSeat();
    playPick(true);
    ctx.notify(`${kart.preset.name} · Aussteigen: A/X halten`);
  }

  /**
   * Out of the kart and back onto your feet, beside it. The capsule that walks
   * around is somewhere else entirely by now, so it is told where the player
   * has ended up.
   */
  private leave(ctx: WorldContext): void {
    const kart = this.driving;
    if (!kart) return;
    this.driving = null;
    this.wheelGrab = null;
    this.exitHeld = 0;
    this.applyHelmet();
    kart.setSeated(false);
    kart.setBraking(0);

    kart.updateWorldMatrix(true, false);
    _spot.set(-1.5, 0, 0.2).applyMatrix4(kart.matrixWorld);
    _spot.y = 0;
    ctx.rig.frozen = false;
    // Mit dem Blickwinkel und nicht mit dem des Karts: wer aussteigt, soll
    // dorthin weiterschauen, wo er gerade hingeschaut hat.
    ctx.rig.placeAt(_spot, this.viewYaw);
    ctx.rig.locomotion.resync?.(ctx.rig);
    this.announceSeat();
    playPick(false);
    ctx.notify('Ausgestiegen');
  }

  /**
   * **Helm auf, Helm ab** — beides an einer Stelle, weil es zwei Dinge sind,
   * die immer zusammen gelten.
   *
   * Von **außen** ist es ein Helm auf dem Kopf: `ctx.wear` setzt ihn dem
   * eigenen Körper auf und sagt ihn allen im Raum an (`core/types.ts`). Von
   * **innen** ist es der Visierrand vor dem Auge — und der ist der eigentliche
   * Zweck der Einstellung: etwas, das stillsteht, während die Welt in der
   * Kurve schwenkt. Wer aussteigt, ist beides wieder los und hat seinen
   * eigenen Hut auf.
   */
  private applyHelmet(): void {
    const ctx = this.context;
    if (!ctx) return;
    const on = this.driving?.settings.helmet === true;
    ctx.wear(on ? 'helmet' : null);

    if (!on) {
      this.visor?.removeFromParent();
      this.visor?.geometry.dispose();
      (this.visor?.material as THREE.Material | undefined)?.dispose();
      this.visor = null;
      return;
    }
    if (this.visor) return;
    const frame = visorFrame();
    frame.layers.set(LAYER_HUD);
    ctx.camera.layers.enable(LAYER_HUD);
    ctx.camera.add(frame);
    this.visor = frame;
  }

  /**
   * Puts the driver in the seat — by the **head**, in all three axes.
   *
   * `placeAt` moves the rig, not the head: in VR the headset sits wherever the
   * player happens to be in their room, and how far above the rig it sits is
   * their own height and their own posture. Both have to be taken out of the
   * sum, otherwise a player who is sitting on a chair ends up with their eyes
   * at seat level while somebody standing looks over the roll bar. So the rig
   * is slid until the head lands on the kart's eye point, sideways *and*
   * vertically — the seat is a place for a head, not for a pair of feet.
   *
   * **Der Ort kommt vom Kart, die Richtung vom Blick.** Der Sitz wandert mit
   * dem Kart, sofort und ohne Verzug — sonst säße man neben ihm. Gedreht wird
   * dagegen nur so schnell, wie der Nachlauf es zulässt (`kartView.ts`), und
   * das ist der ganze Unterschied zwischen „das Kart dreht sich unter mir" und
   * „die Welt wird mir weggerissen".
   */
  private seatDriver(ctx: WorldContext, kart: Kart): void {
    kart.updateWorldMatrix(true, false);
    kart.seat.getWorldPosition(_seat);
    ctx.rig.placeAt(_seat, this.viewYaw);
    ctx.rig.getHeadPosition(_head);
    ctx.rig.position.x += _seat.x - _head.x;
    ctx.rig.position.y += _seat.y - _head.y;
    ctx.rig.position.z += _seat.z - _head.z;
    ctx.rig.updateMatrixWorld(true);
  }

  // --- driving --------------------------------------------------------------

  private updateDriving(dt: number, ctx: WorldContext, kart: Kart): void {
    const left = ctx.input.get('left');
    const right = ctx.input.get('right');
    // A hand whose laser rests on the clipboard (or on any other panel) has
    // lent its trigger to that panel. Per hand, so reading the clipboard with
    // one of them does not also take the throttle out of the other.
    let throttle = ctx.pointer.hoveringWith('right') ? 0 : (right?.trigger.value ?? 0);
    let brake = ctx.pointer.hoveringWith('left') ? 0 : (left?.trigger.value ?? 0);
    let steerWish = 0;
    if (!ctx.renderer.xr.isPresenting) {
      if (this.pressedIs('throttle')) throttle = 1;
      if (this.pressedIs('brake')) brake = 1;
      steerWish = (this.pressedIs('left') ? 1 : 0) - (this.pressedIs('right') ? 1 : 0);
    }

    if (kart.settings.steering === 'wheel') {
      this.updateWheelGrab(ctx, kart);
      // The keyboard still turns the wheel; there is no hand to grab it with.
      if (steerWish !== 0) kart.turnWheelBy(steerWish * STEER_RATE * 0.6 * dt);
    } else {
      const stick = left?.thumbstick.x ?? 0;
      // Stick left is negative, and left is a turn to the left.
      const wish = THREE.MathUtils.clamp(steerWish - stick, -1, 1);
      this.steer += THREE.MathUtils.clamp(wish - this.steer, -STEER_RATE * dt, STEER_RATE * dt);
      kart.showSteer(this.steer);
    }

    const before = { x: kart.motion.x, z: kart.motion.z };
    kart.motion = stepKart(
      kart.motion,
      { throttle, brake, steer: kart.steerInput },
      kart.settings,
      dt,
    );

    const guarded = confineToCourse(
      this.path,
      HALF_WIDTH,
      APRONS,
      kart.motion.x,
      kart.motion.z,
      kart.motion.vx,
      kart.motion.vz,
    );
    kart.motion.x = guarded.x;
    kart.motion.z = guarded.z;
    kart.motion.vx = guarded.vx;
    kart.motion.vz = guarded.vz;
    if (guarded.hit && kmh(kartSpeed(kart.motion)) > 12) {
      playTone({ type: 'sawtooth', from: 180, to: 90, duration: 0.09, gain: 0.04 });
    }

    kart.applyMotion();
    kart.applySteering();
    kart.roll(Math.hypot(kart.motion.x - before.x, kart.motion.z - before.z));
    kart.setBraking(brake);
    this.syncBody(kart);
    // Der Blick zieht nach, und **danach** wird der Sitz gestellt: `seatDriver`
    // dreht den Rig auf genau diesen Winkel.
    this.viewYaw = stepViewYaw(this.viewYaw, kart.motion.yaw, viewFollow(kart.settings), dt);
    this.seatDriver(ctx, kart);
    this.updateLap(dt, ctx, kart);
    this.updateExit(dt, ctx);
  }

  /** True while one of the keys with that job is down. */
  private pressedIs(job: FlatJob): boolean {
    for (const code of this.pressed) {
      if (FLAT_KEYS[code] === job) return true;
    }
    return false;
  }

  /**
   * Steering by turning the wheel: one hand takes hold of it anywhere on the
   * rim, and however far that hand travels around the middle is however far
   * the wheel turns. Letting go — or reaching too far away — hands it back.
   *
   * Gemessen wird dabei **gegen den Blick und nicht gegen das Kart**
   * (`Kart.handAngle`): Seit der Kopf nachzieht, drehen sich die beiden nicht
   * mehr im selben Bild, und eine völlig stillgehaltene Hand wanderte sonst um
   * die Nabe — das Lenkrad drehte sich unter ihr weg und lenkte dabei weiter.
   */
  private updateWheelGrab(ctx: WorldContext, kart: Kart): void {
    const lag = shortestAngle(kart.motion.yaw - this.viewYaw);
    const grab = this.wheelGrab;
    if (grab) {
      const controller = ctx.input.get(grab.hand);
      if (!controller || !controller.tracked || !controller.squeeze.pressed) {
        this.wheelGrab = null;
        return;
      }
      gripAnchor(controller).getWorldPosition(_hand);
      kart.hubPosition(_hub);
      if (_hand.distanceTo(_hub) > WHEEL_HOLD_RANGE) {
        this.wheelGrab = null;
        return;
      }
      const angle = kart.handAngle(_hand, lag);
      kart.turnWheelBy(shortestAngle(angle - grab.angle));
      grab.angle = angle;
      return;
    }

    for (const controller of ctx.input.controllers) {
      if (!controller.tracked || !controller.squeeze.justPressed) continue;
      gripAnchor(controller).getWorldPosition(_hand);
      kart.hubPosition(_hub);
      if (_hand.distanceTo(_hub) > WHEEL_HOLD_RANGE) continue;
      this.wheelGrab = { hand: controller.handedness!, angle: kart.handAngle(_hand, lag) };
      controller.pulse(0.3, 20);
      return;
    }
  }

  /**
   * The way out. A press would be too easy to hit by accident at speed, so it
   * is a short hold — and the sign in front of the driver fills up while it
   * runs, which is what makes the rule visible instead of written down.
   */
  private updateExit(dt: number, ctx: WorldContext): void {
    const kart = this.driving;
    if (!kart) return;
    // `A` also confirms a menu entry, so it only counts from a hand that is
    // not currently pointing at one.
    const held =
      ctx.input.controllers.some(
        (controller) =>
          controller.tracked &&
          controller.primary.pressed &&
          !ctx.pointer.hoveringWith(controller.handedness),
      ) || this.pressedIs('exit');
    this.exitHeld = held ? this.exitHeld + dt : 0;
    kart.setExitProgress(this.exitHeld / EXIT_HOLD);
    if (this.exitHeld >= EXIT_HOLD) this.leave(ctx);
  }

  /** How far round the lap the kart has come, and what that was worth. */
  private updateLap(dt: number, ctx: WorldContext, kart: Kart): void {
    const hit = nearestOnPath(this.path, kart.motion.x, kart.motion.z);
    const step = stepLap(this.lap, hit.along, this.lapLength, dt);
    this.lap = step.state;
    if (!step.completed || this.lap.lastLap === null) return;

    playTone({
      type: 'sine',
      from: step.record ? 620 : 480,
      to: step.record ? 980 : 620,
      duration: 0.22,
      gain: 0.07,
    });
    // Allein sagt eine Runde die Zeit; im Feld sagt sie außerdem, wo man
    // damit steht — das ist beim Rennen die eigentliche Auskunft.
    const place = this.rivals.size > 0 ? ` · P${this.position()}` : '';
    ctx.notify(`Runde ${formatLap(this.lap.lastLap)}${step.record ? ' · Bestzeit!' : ''}${place}`);
    this.drawLapBoard();
  }

  /** Carries the kart's pose over to the body that shoves cones around. */
  private syncBody(kart: Kart): void {
    const entry = this.kartBodies.get(kart);
    if (!entry) return;
    entry.body.setNextKinematicTranslation({ x: kart.motion.x, y: 0.3, z: kart.motion.z });
    _quaternion.setFromAxisAngle(UP, kart.motion.yaw);
    entry.body.setNextKinematicRotation({
      x: _quaternion.x,
      y: _quaternion.y,
      z: _quaternion.z,
      w: _quaternion.w,
    });
  }

  // --- the clipboard --------------------------------------------------------

  /** The whole settings menu of one kart, as the rows on its clipboard. */
  private boardPage(kart: Kart): MenuEntry[] {
    const rows: MenuEntry[] = [
      {
        id: 'kart:leave',
        label: 'Aussteigen',
        sub: 'Oder A/X gedrückt halten',
        icon: 'back',
        accent: 0xffc857,
        run: () => {
          if (this.driving === kart) this.leave(this.context!);
        },
      },
      {
        id: 'kart:steering',
        label: 'Lenkung',
        sub: 'Stick oder Lenkrad in der Hand',
        badge: STEERING_LABELS[kart.settings.steering],
        icon: 'settings',
        accent: 0x4aa8ff,
        run: () => {
          kart.settings.steering = kart.settings.steering === 'stick' ? 'wheel' : 'stick';
          if (kart.settings.steering === 'stick') this.wheelGrab = null;
          this.steer = kart.steerInput;
          kart.refreshSign();
          this.showBoard(kart);
          this.context?.notify(`Lenkung: ${STEERING_LABELS[kart.settings.steering]}`);
        },
      },
    ];

    for (const field of KART_FIELDS) {
      rows.push({
        id: `kart:${field.key}`,
        label: field.label,
        sub: field.sub,
        badge: kartFieldLabel(field, kart.settings),
        icon: 'settings',
        accent: kart.preset.color,
        run: () => this.stepField(kart, field),
      });
    }

    rows.push({
      id: 'kart:helmet',
      label: 'Helm',
      sub: 'Visierrand steht fest im Blick — gegen Übelkeit',
      badge: kart.settings.helmet ? 'auf' : 'ab',
      icon: 'settings',
      accent: 0x9fd8ff,
      checked: kart.settings.helmet,
      run: () => {
        kart.settings.helmet = !kart.settings.helmet;
        this.applyHelmet();
        this.showBoard(kart);
        playPick(true);
        this.context?.notify(kart.settings.helmet ? 'Helm auf' : 'Helm ab');
      },
    });
    rows.push({
      id: 'kart:values',
      label: 'Werte eingeben',
      sub: 'Jede Zahl direkt tippen statt durchzuschalten',
      icon: 'settings',
      accent: kart.preset.color,
      children: KART_FIELDS.map((field) => ({
        id: `kart:type:${field.key}`,
        label: field.label,
        // Die Spanne und nicht der Wert: Der steht schon eine Seite höher, und
        // was hier fehlt, ist die Frage „was darf ich überhaupt eintippen".
        sub: `${field.min}–${field.max} ${field.unit}`.trim(),
        badge: kartFieldLabel(field, kart.settings),
        icon: 'settings',
        accent: kart.preset.color,
        run: () => this.typeField(kart, field),
      })),
    });
    rows.push({
      id: 'kart:reset',
      label: 'Werte zurücksetzen',
      sub: `Wie ${kart.preset.name} aus der Box kam`,
      icon: 'reset',
      accent: 0x9d7bff,
      run: () => {
        Object.assign(kart.settings, clampKart(kart.preset.settings));
        kart.refreshSign();
        this.showBoard(kart);
        this.context?.notify(`${kart.preset.name} zurückgesetzt`);
      },
    });
    rows.push({
      id: 'kart:box',
      label: 'Zurück in die Box',
      sub: 'Setzt genau dieses Kart zurück in seine Bucht',
      icon: 'reset',
      accent: 0x6f7d99,
      run: () => {
        if (this.driving === kart) this.leave(this.context!);
        kart.returnHome();
        this.syncBody(kart);
        this.context?.notify(`${kart.preset.name} steht wieder in der Box`);
      },
    });
    return rows;
  }

  /** One tap moves a value to its next notch. */
  private stepField(kart: Kart, field: KartField): void {
    const value = nextKartStep(field, kart.settings[field.key]);
    kart.settings[field.key] = clampKartField(field, value);
    this.showBoard(kart);
    playPick(true);
    this.context?.notify(`${field.label}: ${kartFieldLabel(field, kart.settings)}`);
  }

  /**
   * **Und derselbe Wert getippt** — der Zifferblock vor dem Kopf
   * (`PortalWorld.askNumber`).
   *
   * Rasten sind zum Ausprobieren da: Man tippt eine Zeile an und merkt am
   * nächsten Bogen, ob es besser wurde. Was sie nicht können, ist das Ende
   * davon — wer weiß, dass sein Kart 0,62 Traktion haben soll, will nicht
   * siebenmal weiterschalten und dabei daran vorbei. Dieselbe Zeile, dieselbe
   * Grenze (`clampKartField`), nur eine andere Eingabe.
   */
  private typeField(kart: Kart, field: KartField): void {
    this.askNumber({
      title: field.label,
      sub: `${kart.preset.name} · ${field.min} bis ${field.max} ${field.unit}`.trim(),
      hint: field.sub,
      value: String(kart.settings[field.key]),
      commit: (value) => {
        kart.settings[field.key] = clampKartField(field, value);
        kart.refreshSign();
        this.showBoard(kart);
        this.context?.notify(`${field.label}: ${kartFieldLabel(field, kart.settings)}`);
      },
    });
  }

  /** Draws the clipboard afresh — every row shows the value it is at. */
  private showBoard(kart: Kart): void {
    kart.setBoard(this.boardPage(kart), kart.preset.tagline);
  }

  /** A long clipboard is scrolled with the stick of the pointing hand. */
  private updateScroll(dt: number, ctx: WorldContext): void {
    const kart = this.karts.find((entry) => entry.board.hovered.hand !== null);
    if (!kart || !kart.board.scrollable) {
      this.scrollArmed = true;
      this.scrollTimer = 0;
      return;
    }
    const y = ctx.input.get(kart.board.hovered.hand ?? 'right')?.thumbstick.y ?? 0;
    if (Math.abs(y) < SCROLL_OFF) {
      this.scrollArmed = true;
      this.scrollTimer = 0;
      return;
    }
    if (Math.abs(y) < SCROLL_ON) return;

    const rows = y > 0 ? 1 : -1;
    if (this.scrollArmed) {
      this.scrollArmed = false;
      this.scrollTimer = SCROLL_FIRST_DELAY;
      kart.board.scrollBy(rows);
      return;
    }
    this.scrollTimer -= dt;
    if (this.scrollTimer > 0) return;
    this.scrollTimer = SCROLL_REPEAT;
    kart.board.scrollBy(rows);
  }

  // --- the place ------------------------------------------------------------

  /**
   * The tarmac, as one ribbon along the centre line.
   *
   * Auf derselben Höhe wie der Asphalt der Boxengasse (`kartPit.ts`), damit an
   * der Zielgeraden keine Stufe zwischen den beiden steht — sie stoßen dort
   * kachelbündig aneinander, und das soll man auch sehen.
   */
  private buildRoad(parent: THREE.Object3D): void {
    parent.add(this.ribbon(0, HALF_WIDTH, TARMAC_TOP, this.tarmac));
    // The white lines just inside the edge; the eye needs them in a corner.
    parent.add(this.ribbon(HALF_WIDTH - 0.25, 0.09, TARMAC_TOP + 0.01, this.paint));
    parent.add(this.ribbon(-(HALF_WIDTH - 0.25), 0.09, TARMAC_TOP + 0.01, this.paint));
  }

  /**
   * A strip along the track: `offset` metres off the middle, `half` metres to
   * each side of that, laid at `y`.
   */
  private ribbon(offset: number, half: number, y: number, material: THREE.Material): THREE.Mesh {
    const count = this.path.length;
    const positions = new Float32Array(count * 2 * 3);
    const indices: number[] = [];

    for (let i = 0; i < count; i++) {
      const point = this.path[i]!;
      const next = this.path[(i + 1) % count]!;
      const previous = this.path[(i - 1 + count) % count]!;
      // The tangent of the whole neighbourhood, so the strip does not kink.
      const tx = next.x - previous.x;
      const tz = next.z - previous.z;
      const length = Math.hypot(tx, tz) || 1;
      // Left-hand normal of the tangent, seen from above.
      const nx = tz / length;
      const nz = -tx / length;
      const base = i * 6;
      positions[base] = point.x + nx * (offset + half);
      positions[base + 1] = y;
      positions[base + 2] = point.z + nz * (offset + half);
      positions[base + 3] = point.x + nx * (offset - half);
      positions[base + 4] = y;
      positions[base + 5] = point.z + nz * (offset - half);

      const a = i * 2;
      const b = ((i + 1) % count) * 2;
      indices.push(a, a + 1, b + 1, a, b + 1, b);
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = 'surface:track';
    return mesh;
  }

  /**
   * Red and white kerbs, laid along both edges of the tarmac — nur eben nicht
   * dort, wo die Boxengasse liegt: Dort ist kein Rand, sondern die Ausfahrt.
   */
  private buildKerbs(parent: THREE.Object3D): void {
    const step = 2.2;
    let index = 0;
    for (let distance = 0; distance < this.lapLength; distance += step) {
      const point = this.pointAt(distance);
      const material = index % 2 === 0 ? this.kerbRed : this.kerbWhite;
      for (const side of [1, -1]) {
        const x = point.x + point.nx * side * (HALF_WIDTH + 0.28);
        const z = point.z + point.nz * side * (HALF_WIDTH + 0.28);
        if (this.overPit(x, z)) continue;
        const kerb = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.07, step * 0.95), material);
        kerb.position.set(x, 0.035, z);
        kerb.rotation.y = Math.atan2(-point.tx, -point.tz);
        parent.add(kerb);
      }
      index++;
    }
  }

  /** Stacks of tyres outside the kerbs — solid, so nobody walks off the map. */
  private buildBarriers(parent: THREE.Object3D): void {
    for (let distance = 0; distance < this.lapLength; distance += BARRIER_SPACING) {
      const point = this.pointAt(distance);
      for (const side of [1, -1]) {
        const x = point.x + point.nx * side * (HALF_WIDTH + BARRIER_OFFSET);
        const z = point.z + point.nz * side * (HALF_WIDTH + BARRIER_OFFSET);
        if (this.overPit(x, z)) continue;
        const stack = new THREE.Mesh(new THREE.BoxGeometry(1.1, 0.6, 1.1), this.tyre);
        stack.position.set(x, 0.3, z);
        stack.rotation.y = Math.atan2(-point.tx, -point.tz);
        parent.add(stack);
        stack.updateWorldMatrix(true, false);
        this.physics!.addStatic(stack, { membership: GROUP_WORLD, filter: ALL_GROUPS });
        this.solids.push(stack);
      }
    }
  }

  /**
   * Ob an dieser Stelle die Boxengasse liegt.
   *
   * Randsteine und Reifenstapel folgen der Mittellinie und wissen von der
   * Gasse nichts — ohne diese Frage stünde die halbe Bande zwischen den Karts.
   */
  private overPit(x: number, z: number): boolean {
    return APRONS.some((apron) =>
      insideApron(
        {
          x0: apron.x0 - PIT_CLEAR,
          z0: apron.z0 - PIT_CLEAR,
          x1: apron.x1 + PIT_CLEAR,
          z1: apron.z1 + PIT_CLEAR,
        },
        x,
        z,
      ),
    );
  }

  /** Start line, and the two boards standing beside it. */
  private buildStart(parent: THREE.Object3D): void {
    const point = this.pointAt(0);
    const line = new THREE.Mesh(
      new THREE.PlaneGeometry(HALF_WIDTH * 2, 0.7),
      new THREE.MeshBasicMaterial({ map: checkerTexture(), toneMapped: false }),
    );
    line.rotation.x = -Math.PI / 2;
    // Laid flat first, then turned so its width runs across the track.
    line.rotation.z = Math.atan2(point.tx, point.tz);
    line.position.set(point.x, TARMAC_TOP + 0.015, point.z);
    parent.add(line);

    // Beide Tafeln stehen **rechts** der Zielgeraden: links liegt die
    // Boxengasse, und eine Tafel auf Stelzen mitten in der Gasse wäre das
    // Erste, was jemand beim Losfahren umfährt.
    this.lapBoard = new TextPlane({
      width: 4.4,
      height: 1.5,
      title: 'Rundenzeiten',
      accent: 0xffc857,
    });
    this.standBoard(parent, this.lapBoard, 4, -1, 2.2);
    this.drawLapBoard();

    const sign = new TextPlane({
      width: 4,
      height: 1.3,
      title: 'Gokart',
      body: 'Aus der Box nach rechts auf die Gerade. Rechter Trigger gibt Gas, linker bremst, der linke Stick lenkt. Aussteigen: A/X halten. Alles Weitere steht auf dem Klemmbrett im Kart.',
      accent: 0x4aa8ff,
    });
    this.standBoard(parent, sign, 14, -1, 2);
  }

  /**
   * Puts a board on two posts beside the track, turned to face the tarmac.
   *
   * @param along  how far round the lap it stands
   * @param side   1 outside the left-hand edge, -1 outside the right-hand one
   */
  private standBoard(
    parent: THREE.Object3D,
    board: TextPlane,
    along: number,
    side: number,
    height: number,
  ): void {
    const point = this.pointAt(along);
    const out = HALF_WIDTH + 4.2;
    const x = point.x + point.nx * side * out;
    const z = point.z + point.nz * side * out;
    // The plane looks along +Z, so it is turned until that points inwards.
    const yaw = Math.atan2(-point.nx * side, -point.nz * side);
    board.position.set(x, height, z);
    board.rotation.y = yaw;
    parent.add(board);

    for (const offset of [-1.5, 1.5]) {
      const px = x + Math.cos(yaw) * offset;
      const pz = z - Math.sin(yaw) * offset;
      this.slab(parent, this.tyre, [0.12, height, 0.12], [px, height / 2, pz], false);
    }
    // One bright panel behind each board — the only thing a portal sticks to
    // out here besides the ground.
    this.slab(
      parent,
      this.panel,
      [0.2, 2, 3.4],
      [x + point.nx * side * 0.4, 1, z + point.nz * side * 0.4],
      true,
    );
  }

  /**
   * **Die Karts in der Boxengasse**, eines vor jeder Bucht.
   *
   * Vorher standen sie in Zweierreihen auf der Strecke, wie ein Startfeld —
   * und wer ausstieg, stand mitten auf der Fahrbahn, während der Nächste
   * angefahren kam. Die Gasse ist der Ort, an dem ein Kart wartet: neben der
   * Strecke, mit der Nase in Fahrtrichtung, und mit Platz zum Herumgehen.
   */
  private buildPitLane(): void {
    const physics = this.physics!;
    const spots = pitSpots();
    KART_PRESETS.forEach((preset, index) => {
      const kart = new Kart(preset);
      const spot = spots[index % spots.length]!;
      kart.placeHome(spot.x, spot.z, spot.yaw);
      this.root.add(kart);
      this.karts.push(kart);

      kart.updateWorldMatrix(true, false);
      // Solid enough to knock cones over, but never the player: a kart that
      // shoves the capsule you are standing in launches you across the field.
      this.kartBodies.set(
        kart,
        physics.addKinematic(kart, {
          halfExtents: new THREE.Vector3(0.5, 0.3, 0.85),
          membership: GROUP_WORLD,
          filter: ALL_GROUPS & ~GROUP_PLAYER,
        }),
      );
      this.syncBody(kart);
    });
  }

  /** A point that far around the lap, with the tangent and normal there. */
  private pointAt(distance: number): {
    x: number;
    z: number;
    tx: number;
    tz: number;
    nx: number;
    nz: number;
  } {
    const total = this.lapLength;
    let left = ((distance % total) + total) % total;
    for (let i = 0; i < this.path.length; i++) {
      const a = this.path[i]!;
      const b = this.path[(i + 1) % this.path.length]!;
      const dx = b.x - a.x;
      const dz = b.z - a.z;
      const length = Math.hypot(dx, dz);
      if (left > length && i < this.path.length - 1) {
        left -= length;
        continue;
      }
      const t = length > 0 ? left / length : 0;
      const tx = length > 0 ? dx / length : 0;
      const tz = length > 0 ? dz / length : -1;
      return { x: a.x + dx * t, z: a.z + dz * t, tx, tz, nx: tz, nz: -tx };
    }
    return { x: 0, z: 0, tx: 0, tz: -1, nx: -1, nz: 0 };
  }

  /**
   * Die Tafel: allein die eigenen Zeiten, zu mehreren das Feld.
   *
   * Wer allein fährt, will wissen, ob die letzte Runde besser war als die
   * beste. Wer zu zweit fährt, will wissen, ob er vorn liegt — und dafür ist
   * eine Bestzeit die falsche Antwort.
   */
  private drawLapBoard(): void {
    if (!this.lapBoard) return;
    const running = this.driving ? `Läuft: ${formatLap(this.lap.time)}` : 'Kein Kart besetzt';
    if (this.rivals.size === 0) {
      this.lapBoard.setText(
        this.lap.lastLap === null ? 'Noch keine Runde' : `Letzte ${formatLap(this.lap.lastLap)}`,
        `${this.lap.bestLap === null ? 'Beste: —' : `Beste: ${formatLap(this.lap.bestLap)}`} · ${running}`,
      );
      return;
    }
    const net = this.context?.net;
    const lines = net ? raceLines(this.racers(), net.localId) : [];
    this.lapBoard.setText(
      `P${this.position()} von ${lines.length} · ${running}`,
      lines.join('   '),
    );
  }

  // --- zu zweit fahren ------------------------------------------------------

  /**
   * Das ganze Feld, eigenes Kart eingeschlossen — die Grundlage für
   * Reihenfolge und Tafel (`kartRace.ts`, mit Test).
   */
  private racers(): Racer[] {
    const net = this.context?.net;
    const field: Racer[] = [];
    if (net) {
      field.push({
        id: net.localId,
        name: net.name,
        kart: this.driving ? this.karts.indexOf(this.driving) : null,
        laps: this.lap.laps,
        progress: this.lap.progress,
        lastLap: this.lap.lastLap,
        bestLap: this.lap.bestLap,
      });
    }
    for (const [id, rival] of this.rivals) {
      field.push({
        id,
        name: rival.name,
        kart: rival.kart,
        laps: rival.laps,
        progress: rival.progress,
        lastLap: rival.lastLap,
        bestLap: rival.bestLap,
      });
    }
    return field;
  }

  /** Der eigene Platz im Feld, von eins an gezählt. */
  private position(): number {
    const net = this.context?.net;
    if (!net) return 1;
    return standings(this.racers()).findIndex((racer) => racer.id === net.localId) + 1;
  }

  /** Ob in diesem Kart schon ein Mitspieler sitzt. */
  private takenByOther(kart: Kart): boolean {
    const index = this.karts.indexOf(kart);
    for (const rival of this.rivals.values()) {
      if (rival.kart === index) return true;
    }
    return false;
  }

  /** Schreibt auf jedes Kart, wer darin sitzt — oder dass es frei ist. */
  private markTaken(): void {
    for (const kart of this.karts) {
      let name: string | null = null;
      const index = this.karts.indexOf(kart);
      for (const rival of this.rivals.values()) {
        if (rival.kart === index) name = rival.name;
      }
      kart.setTaken(name);
    }
  }

  /** Sagt dem Raum, wo man sitzt — beim Ein- und beim Aussteigen. */
  private announceSeat(): void {
    const net = this.context?.net;
    if (!net) return;
    const message: KartMessage = {
      t: 'seat',
      kart: this.driving ? this.karts.indexOf(this.driving) : null,
      name: net.name,
    };
    net.emit(CHANNEL, message);
    if (this.driving) this.sendDrive(this.driving);
  }

  /** Eine Pose samt Rundenstand. */
  private sendDrive(kart: Kart): void {
    const net = this.context?.net;
    if (!net) return;
    const message: KartMessage = {
      t: 'drive',
      kart: this.karts.indexOf(kart),
      x: round(kart.motion.x),
      z: round(kart.motion.z),
      yaw: round(kart.motion.yaw),
      steer: round(kart.steerInput),
      laps: this.lap.laps,
      progress: round(this.lap.progress),
      last: this.lap.lastLap,
      best: this.lap.bestLap,
    };
    net.emit(CHANNEL, message);
  }

  private receive(ctx: WorldContext, message: KartMessage, from: string): void {
    switch (message.t) {
      case 'hello':
        // Wer dazukommt, weiß von niemandem etwas; also sagt jeder einmal,
        // wo er sitzt.
        this.announceSeat();
        return;
      case 'seat': {
        if (message.kart === null || !this.karts[message.kart]) {
          this.releaseRival(from);
          return;
        }
        const kart = this.karts[message.kart]!;
        // Zwei Hände an einem Lenkrad: es gewinnt die kleinere Id. Das ist auf
        // beiden Rechnern dieselbe Antwort und braucht keine Wahl.
        if (this.driving === kart && from < ctx.net.localId) {
          this.leave(ctx);
          ctx.notify(`${kart.preset.name} war schon besetzt`);
        }
        const rival = this.rival(from, message.name);
        rival.kart = message.kart;
        rival.name = message.name || rival.name;
        rival.primed = false;
        this.markTaken();
        this.drawLapBoard();
        return;
      }
      case 'drive': {
        if (!this.karts[message.kart]) return;
        const rival = this.rival(from);
        rival.kart = message.kart;
        rival.laps = message.laps;
        rival.progress = message.progress;
        rival.lastLap = message.last;
        rival.bestLap = message.best;
        rival.steer = message.steer;
        rival.target.x = message.x;
        rival.target.z = message.z;
        rival.target.yaw = message.yaw;
        this.markTaken();
        return;
      }
      case 'home': {
        for (const kart of this.karts) {
          // Das eigene Kart nicht: wer gerade fährt, würde sonst mitten in
          // einer Kurve in der Box stehen.
          if (kart === this.driving) continue;
          kart.returnHome();
          this.syncBody(kart);
        }
        for (const rival of this.rivals.values()) rival.primed = false;
        return;
      }
    }
  }

  /** Der Eintrag zu einer Peer-Id, notfalls ein frischer. */
  private rival(id: string, name?: string): Rival {
    const existing = this.rivals.get(id);
    if (existing) return existing;
    const fresh: Rival = {
      name: name || this.context?.net.peers.get(id)?.name || 'Mitspieler',
      kart: 0,
      laps: 0,
      progress: 0,
      lastLap: null,
      bestLap: null,
      target: { x: 0, z: 0, yaw: 0 },
      steer: 0,
      primed: false,
    };
    this.rivals.set(id, fresh);
    return fresh;
  }

  /** Er ist ausgestiegen oder gegangen: sein Kart ist wieder frei. */
  private releaseRival(id: string): void {
    if (!this.rivals.delete(id)) return;
    this.markTaken();
    this.drawLapBoard();
  }

  /**
   * Die Karts der anderen: sie fahren hier nicht, sie werden nachgezogen.
   *
   * Gerechnet wird ein Kart immer nur dort, wo jemand darin sitzt — das ist
   * die einzige Stelle, an der Gas, Bremse und Lenkung wirklich bekannt sind.
   * Alle anderen bekommen zwanzigmal in der Sekunde die Pose und laufen ihr
   * weich hinterher; ein verlorenes Paket ist damit ein Ruckler und kein
   * Kart, das durch die Leitplanke kriecht.
   */
  private updateRivals(dt: number, ctx: WorldContext): void {
    for (const id of [...this.rivals.keys()]) {
      if (!ctx.net.peers.has(id)) this.releaseRival(id);
    }
    const follow = 1 - Math.exp(-dt / FOLLOW_TAU);
    for (const rival of this.rivals.values()) {
      const kart = this.karts[rival.kart];
      if (!kart || kart === this.driving) continue;
      const before = { x: kart.motion.x, z: kart.motion.z };
      const gap = Math.hypot(rival.target.x - kart.motion.x, rival.target.z - kart.motion.z);
      const t = !rival.primed || gap > SNAP_DISTANCE ? 1 : follow;
      kart.motion.x += (rival.target.x - kart.motion.x) * t;
      kart.motion.z += (rival.target.z - kart.motion.z) * t;
      kart.motion.yaw += shortestAngle(rival.target.yaw - kart.motion.yaw) * t;
      rival.primed = true;
      kart.applyMotion();
      kart.showSteer(rival.steer);
      kart.applySteering();
      kart.roll(Math.hypot(kart.motion.x - before.x, kart.motion.z - before.z));
      this.syncBody(kart);
    }
  }

  /** Die eigene Pose hinaus, zwanzigmal in der Sekunde. */
  private updateSend(dt: number): void {
    const kart = this.driving;
    if (!kart) return;
    this.sendTimer += dt;
    if (this.sendTimer < SEND_INTERVAL) return;
    this.sendTimer = 0;
    this.sendDrive(kart);
  }
}

const UP = new THREE.Vector3(0, 1, 0);

/** Millimeter und Milliradiant reichen über das Netz; der Rest ist Bandbreite. */
function round(value: number): number {
  return Math.round(value * 1000) / 1000;
}

/** The black and white squares of a start line, drawn once. */
function checkerTexture(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 32;
  const ctx = canvas.getContext('2d')!;
  const cell = 16;
  for (let x = 0; x < canvas.width / cell; x++) {
    for (let y = 0; y < canvas.height / cell; y++) {
      ctx.fillStyle = (x + y) % 2 === 0 ? '#f2f4f8' : '#171b24';
      ctx.fillRect(x * cell, y * cell, cell, cell);
    }
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}
